import { IFundsListCriteria } from '@apps/Finances/@types/funds.dto.types';
import { IFund } from '@apps/Finances/@types/funds.types';
import { showModal } from '@ui-kit/Modal';

import FundsList from '../FundsList';

export const selectFundInModalAsync = (criteria?: IFundsListCriteria): Promise<IFund> => {
  return new Promise((res) => {
    showModal({
      title: 'Выбор фонда',
      scrollable: true,
      flushBody: true,
      style: { width: 400, maxHeight: 480 },
      children: (clos) => (
        <FundsList
          flush
          criteria={criteria}
          onSelect={(up) => {
            res(up);
            clos();
          }}
        />
      ),
    });
  });
};
