import React, { useContext } from 'react';

import ChevronDown from '@pohodnik/icons/svg/Chevrons/ChevronDown';
import ChevronUp from '@pohodnik/icons/svg/Chevrons/ChevronUp';
import ChatFill from '@pohodnik/icons/svg/Communication/ChatFill';
import clsx from 'clsx';
import { Link } from 'react-router-dom';

import { getHikingAccessGroupAsync } from '@apps/Hiking/@services/hikingRules.service';
import { selectHikerAsync } from '@components/HikerSelector/hikerSelectHelper';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import { formatFinance } from '@helpers/formatHelper';
import { round } from '@helpers/mathHelper';
import { open } from '@helpers/navigationHelper';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert from '@ui-kit/Alert';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohContainer from '@ui-kit/layout/Container';
import PohList from '@ui-kit/List';
import { confirmModal, showModal } from '@ui-kit/Modal';

import styles from './styles.module.less';
import { AuthContext } from '../../../../contexts/AuthContext';
import { getHikingDataAsync } from '../../@services/hiking.service';
import {
  deleteHikingFinancePayment,
  deleteHikingFinancesReceipt,
  getHikingFinancesPayments,
  getHikingFinancesReceipts,
  getHikingReceiptCategories,
} from '../../@services/hikingFinances.service';
import { HikingAccessGroup, HikingPosition } from '../../@types/hiking.rules';
import { IHiker, IHikingData } from '../../@types/hiking.types';
import {
  IHikingFinanceCurrency,
  IHikingPayment,
  IHikingReceipt,
  IHikingReceiptCategory,
} from '../../@types/hikingFinances.types';
import HikingFinanceReceiptItem from '../components/HikingFinanceReceiptItem';
import {
  editOrAddPaymentAsync,
  editOrAddReceiptAsync,
  editReceiptParticipationAsync,
  viewReceipt,
} from '../HikingFinancesModals/modalHelper';

interface IHikingFinancesPageProps {
  id_hiking: number;
}

const HikingFinancesPage: React.FC<IHikingFinancesPageProps> = ({ id_hiking }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);

  const [categories, setCategories] = React.useState<IHikingReceiptCategory[]>([]);

  const [payments, setPayments] = React.useState<IHikingPayment[]>([]);
  const [receipts, setReceipts] = React.useState<IHikingReceipt[]>([]);

  const [err, setErr] = React.useState<string | undefined>(undefined);
  const [canEdit, setCanEdit] = React.useState(true);

  const [isReceiptsCollapsed, setIsReceiptsCollapsed] = React.useState(false);
  const [isPaymentsCollapsed, setIsPaymentsCollapsed] = React.useState(false);

  const [frozen, setFrozen] = React.useState(true);

  const frozenText = 'Редактирование не доступно';

  const authContext = useContext(AuthContext);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);
        const hData = await getHikingDataAsync(id_hiking);
        setHikingData(hData);

        const categoriesData = await getHikingReceiptCategories();
        setCategories(categoriesData);

        const receiptsData = await getHikingFinancesReceipts({ id_hiking });
        setReceipts(receiptsData);

        const paymentsData = await getHikingFinancesPayments(id_hiking);
        setPayments(paymentsData);

        const accessGroup = await getHikingAccessGroupAsync(id_hiking);
        const hasPriv = [
          HikingAccessGroup.Full,
          HikingAccessGroup.All,
          HikingAccessGroup.Boss,
          HikingAccessGroup.Money,
        ].includes(accessGroup);
        setCanEdit(hasPriv);

        setFrozen(!hasPriv && new Date().getTime() - hData.finish.getTime() > 86400 * 1000 * 21);
      } catch (e) {
        setErr((e as Error).message);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [id_hiking]);

  const handleAddReceipt = async (withSelectUser: boolean) => {
    if (!hikingData) return;
    if (!authContext.user) return;

    let user = {
      id: authContext.user.id,
      name: authContext.user.name,
      surname: authContext.user.surname,
      photo: authContext.user.photo,
    };

    if (withSelectUser) {
      const hiker = await selectHikerAsync(id_hiking, { withMe: true });
      user = {
        id: hiker.idUser,
        name: hiker.name,
        surname: hiker.surname,
        photo: hiker.photo[50],
      };
    }

    const emptyReceipt: IHikingReceipt = {
      id: 0,
      name: '',
      date: new Date(),
      total: 0,
      totalByItems: 0,
      images: {
        orig: null,
        600: null,
        100: null,
      },
      participation: null,
      user,
      author: authContext.user,
      idCategory: null,
      currency: null,
      totalInCurrency: null,
      pdf_url: null,
      html: null,
      qr_code: null,
    };

    const newReceipt = await editOrAddReceiptAsync({
      receipt: emptyReceipt,
      hikingData,
      categories,
    });

    setReceipts((cur) => [...cur, newReceipt]);
    notificationHelper.success('Чек успешно добавлен');
  };
  const handleEditReceipt = async (receipt: IHikingReceipt) => {
    if (!hikingData) return;
    if (!authContext.user) return;

    const newReceipt = await editOrAddReceiptAsync({ receipt, hikingData, categories });

    setReceipts((cur) => cur.map((c) => (c.id === newReceipt.id ? newReceipt : c)));
    notificationHelper.success('Чек успешно обновлен');
  };
  const handleEditReceiptParticipation = async (receipt: IHikingReceipt) => {
    if (!hikingData) return;
    if (!authContext.user) return;

    const newReceipt = await editReceiptParticipationAsync({ receipt, hikingData });

    setReceipts((cur) => cur.map((c) => (c.id === newReceipt.id ? newReceipt : c)));
    notificationHelper.success('Чек успешно обновлен');
  };

  const handleDeleteReceipt = async (receipt: IHikingReceipt) => {
    if (!hikingData) return;
    if (!authContext.user) return;

    confirmModal({
      children: `Удалить чек ${formatFinance(receipt.total)}?`,
      onConfirm: async () => {
        const ok = await deleteHikingFinancesReceipt(receipt.id, hikingData.id);
        if (ok) {
          setReceipts((cur) => cur.filter((c) => c.id !== receipt.id));
          notificationHelper.success('Удалено!');
        }
      },
    });
  };

  const handleAddPayment = async () => {
    if (!hikingData) return;
    if (!authContext.user) return;

    const emptyPayment: IHikingPayment = {
      id: 0,
      total: 0,
      date: new Date(),
      comment: '',
      userFrom: {
        id: 0,
        name: '',
        surname: '',
        photo: '',
      },
      userTo: {
        id: +authContext.user.id,
        name: authContext.user.name,
        surname: authContext.user.surname,
        photo: authContext.user.photo,
      },
      fundFrom: null,
      fundTo: null,
      currency: null,
      totalInCurrency: null,
      dateCreate: new Date(),
      author: {
        id: +authContext.user.id,
      },
    };

    const newPayment = await editOrAddPaymentAsync(emptyPayment, hikingData);

    setPayments((cur) => [...cur, newPayment]);
    notificationHelper.success('Взнос успешно добавлен');
  };
  const handleEditPayment = async (payment: IHikingPayment) => {
    if (!hikingData) return;
    if (!authContext.user) return;

    const newPayment = await editOrAddPaymentAsync(payment, hikingData);

    setPayments((cur) => cur.map((c) => (c.id === payment.id ? newPayment : c)));
    notificationHelper.success('Сохранено!');
  };
  const handleDeletePayment = async (payment: IHikingPayment) => {
    if (!hikingData) return;
    if (!authContext.user) return;

    confirmModal({
      children: `Удалить взнос ${formatFinance(payment.total)}?`,
      onConfirm: async () => {
        const ok = await deleteHikingFinancePayment(payment.id, hikingData.id);
        if (ok) {
          setPayments((cur) => cur.filter((c) => c.id !== payment.id));
          notificationHelper.success('Удалено!');
        }
      },
    });
  };

  if (isLoading) {
    return <PageLoader />;
  }

  if (err || !hikingData) {
    return <PohAlert>{err}</PohAlert>;
  }

  let totalExpenses = 0;
  let totalPayments = 0;

  const totalByCategories: Record<IHikingReceiptCategory['id'], number> = {};

  const hikerTotalExpenses: Record<IHiker['idUser'], number> = {}; // Сумма затрат каждого участника
  const hikerTotalPayments: Record<IHiker['idUser'], number> = {}; // Сумма взносов каждого участника
  const hikerTotalIncomePayments: Record<IHiker['idUser'], number> = {}; // Сумма взносов
  const hikerTotalFundsPayments: Record<IHiker['idUser'], number> = {}; // Сумма взносов в фонды
  const hikerRates: Record<IHiker['idUser'], number> = {}; // Коэффициент каждого участника (при неполном участии)
  const hikerDebt: Record<IHiker['idUser'], number> = {}; // Остаток долга каждого участника
  const hikerDebtInfo: Record<
    IHiker['idUser'],
    {
      type: 'participation' | 'rate' | 'equally';
      total: number;
      receipt: IHikingReceipt;
      comment?: string;
    }[]
  > = {}; // из чего сост долг каждого участника

  const fullDuration = hikingData.finish.getTime() - hikingData.start.getTime();

  hikingData.hikers.forEach((hiker) => {
    const userStartDate = hiker.dateFrom ?? hikingData.start;
    const userFinishDate = hiker.dateTo ?? hikingData.finish;

    const userDuration = userFinishDate.getTime() - userStartDate.getTime();
    const userRate = userDuration / fullDuration;

    hikerRates[hiker.idUser] = userRate;
  });

  receipts.forEach((receipt) => {
    if (!hikerTotalExpenses[receipt.user.id]) hikerTotalExpenses[receipt.user.id] = 0;
    hikerTotalExpenses[receipt.user.id] += receipt.total;
    totalExpenses += receipt.total;

    if (receipt.idCategory && !totalByCategories[receipt.idCategory])
      totalByCategories[receipt.idCategory] = 0;
    if (receipt.idCategory) totalByCategories[receipt.idCategory] += receipt.total;

    const participationIds = receipt.participation?.map?.((p) => p.id) ?? [];

    hikingData.hikers.forEach((hiker) => {
      if (!hikerDebt[hiker.idUser]) hikerDebt[hiker.idUser] = 0;
      if (!hikerDebtInfo[hiker.idUser]) hikerDebtInfo[hiker.idUser] = [];

      if (participationIds.length) {
        // если чек не на всех
        if (participationIds.includes(hiker.idUser)) {
          const equalPart = receipt.total / participationIds.length;
          hikerDebt[hiker.idUser] += equalPart;
          hikerDebtInfo[hiker.idUser].push({ receipt, type: 'participation', total: equalPart });
        } else {
          // пользователь на этот чек не скидывается
        }
      } else {
        const equalPart = receipt.total / hikingData.hikers.length;

        const partialHikers = hikingData.hikers.filter(({ idUser }) => hikerRates[idUser] !== 1);
        const pieceSum = partialHikers.reduce((acc, { idUser }) => {
          return acc + equalPart * hikerRates[idUser];
        }, 0);

        if (hikerRates[hiker.idUser] !== 1) {
          const total = equalPart * hikerRates[hiker.idUser];
          hikerDebt[hiker.idUser] += total;
          hikerDebtInfo[hiker.idUser].push({
            receipt,
            type: 'rate',
            total: total,
            comment: `С понижающим коэффициентом ${round(hikerRates[hiker.idUser])} (${formatFinance(equalPart)} × ${round(hikerRates[hiker.idUser] * 100)}%)`,
          });
        } else {
          const total =
            (receipt.total - pieceSum) / (hikingData.hikers.length - partialHikers.length);
          hikerDebt[hiker.idUser] += total;
          const rate = total / equalPart;
          hikerDebtInfo[hiker.idUser].push({
            receipt,
            type: 'equally',
            total,
            comment:
              pieceSum > 0
                ? `С повышающим коэффициентом ${round(rate)} (${formatFinance(equalPart)} × ${round(rate * 100)}%) т.к. есть участники с неполным участием`
                : ``,
          });
        }
      }
    });
  });

  payments.forEach((payment) => {
    const fromKey = payment.fundFrom?.id ? payment.fundFrom?.id * -1 : (payment.userFrom?.id ?? 0);
    const toKey = payment.fundTo?.id ? payment.fundTo.id * -1 : (payment.userTo?.id ?? 0);

    if (!hikerTotalPayments[fromKey]) hikerTotalPayments[fromKey] = 0;
    if (!hikerTotalFundsPayments[fromKey]) hikerTotalFundsPayments[fromKey] = 0;
    if (!hikerTotalIncomePayments[toKey]) hikerTotalIncomePayments[toKey] = 0;

    hikerTotalPayments[fromKey] += payment.fundTo?.id ? 0 : payment.total;
    hikerTotalFundsPayments[fromKey] += payment.fundTo?.id ? payment.total : 0;
    hikerTotalIncomePayments[toKey] += payment.total;

    totalPayments += payment.total;
  });

  return (
    <div>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name },
          { href: `/hiking/${id_hiking}/finances`, text: 'Финансы', active: true },
        ]}
      />
      <PohContainer>
        <PageHeader title={`Финансы похода «${hikingData.name}»`}>
          <PohButton
            size={ButtonSize.Small}
            variant={ButtonVariant.Link}
            onClick={() => open(`/hiking/${id_hiking}/comments#${HikingPosition.Finansist}`)}
            className="d-flex align-items-center"
          >
            <ChatFill />
            &nbsp;Обсудить
          </PohButton>
        </PageHeader>

        <p>Добавьте чеки отражающие затраты на групповые закупки</p>

        <h4 className="d-flex align-items-center mt-3">
          <PohButton
            onClick={() => setIsReceiptsCollapsed((c) => !c)}
            icon={true}
            size={ButtonSize.Small}
            className="me-2"
          >
            {isReceiptsCollapsed ? <ChevronDown /> : <ChevronUp />}
          </PohButton>
          Чеки
          {!frozen && (
            <aside className="ms-auto">
              {canEdit && (
                <PohButton
                  size={ButtonSize.Small}
                  variant={ButtonVariant.OutlineWarning}
                  onClick={() => handleAddReceipt(true)}
                  title={frozen ? frozenText : ''}
                >
                  <span className="d-none d-md-block">Добавить чужой чек</span>
                  <span className="d-block d-md-none">+ Чужой чек</span>
                </PohButton>
              )}
              <PohButton
                className="ms-2"
                size={ButtonSize.Small}
                variant={ButtonVariant.Success}
                onClick={() => handleAddReceipt(false)}
                title={frozen ? frozenText : ''}
              >
                <span className="d-none d-md-block">Добавить свой чек</span>
                <span className="d-block d-md-none">+ Свой чек</span>
              </PohButton>
            </aside>
          )}
        </h4>
        {!isReceiptsCollapsed && (
          <>
            <PohList
              data={receipts.map((receipt) => {
                return {
                  key: receipt.id,
                  action: true,
                  onClick: () => viewReceipt(receipt, hikingData),
                  content: authContext?.user && (
                    <HikingFinanceReceiptItem
                      hikingData={hikingData}
                      receipt={receipt}
                      categories={categories}
                      onDelete={
                        !frozen && (canEdit || receipt.author.id === +authContext.user.id)
                          ? handleDeleteReceipt
                          : undefined
                      }
                      onEdit={
                        !frozen && (canEdit || receipt.author.id === +authContext.user.id)
                          ? handleEditReceipt
                          : undefined
                      }
                      onEditParts={
                        !frozen && (canEdit || receipt.author.id === +authContext.user.id)
                          ? handleEditReceiptParticipation
                          : undefined
                      }
                    />
                  ),
                };
              })}
            />

            <div className="mt-3 mb-5 d-flex flex-wrap">
              {totalExpenses > 0 && (
                <div
                  style={{ flexBasis: 60, marginRight: 8, marginBottom: 4 }}
                  className="border-end pe-4 me-4"
                >
                  <div
                    style={{ borderBottom: `2px solid transparent` }}
                    className="p-1 text-center"
                  >
                    <PohBadge
                      variant={BadgeVariant.Success}
                      title={Object.values(
                        receipts.reduce<
                          Record<number, { currency: IHikingFinanceCurrency; total: number }>
                        >((acc, r) => {
                          const cur = r.currency ?? {
                            id: 1,
                            shortName: 'RUB',
                            name: '',
                            symbol: '₽',
                          };

                          if (!acc[cur.id]) {
                            acc[cur.id] = {
                              currency: cur,
                              total: 0,
                            };
                          }

                          acc[cur.id].total += r.totalInCurrency ?? r.total;

                          return acc;
                        }, {}),
                      )
                        .map((o) => {
                          return [
                            o.currency.shortName,
                            formatFinance(o.total, 0, o.currency.symbol),
                          ].join('\t');
                        })
                        .join('\n')}
                    >
                      {formatFinance(totalExpenses)}
                    </PohBadge>
                  </div>
                  <small>
                    &nbsp;&nbsp;<b title={totalPayments.toString()}>Всего</b>
                  </small>
                </div>
              )}
              {Object.entries(totalByCategories).map(([categoryId, categoryTotal]) => {
                const cat = categories.find((c) => c.id === +categoryId);
                return (
                  <div key={cat?.id} style={{ flexBasis: 60, marginRight: 8, marginBottom: 4 }}>
                    <div style={{ borderBottom: `2px solid ${cat?.color}` }}>
                      {formatFinance(categoryTotal)}
                    </div>
                    <small>{cat?.name}</small>
                  </div>
                );
              })}
            </div>
          </>
        )}

        <h4 className="mt-3 d-flex align-items-center">
          <PohButton
            onClick={() => setIsPaymentsCollapsed((c) => !c)}
            icon={true}
            size={ButtonSize.Small}
            className="me-2"
          >
            {isPaymentsCollapsed ? <ChevronDown /> : <ChevronUp />}
          </PohButton>
          Взносы
          <aside className="ms-auto">
            {!frozen && canEdit && (
              <PohButton size={ButtonSize.Small} onClick={() => handleAddPayment()}>
                Добавить взнос
              </PohButton>
            )}
          </aside>
        </h4>

        {!isPaymentsCollapsed && (
          <div
            className={styles.finTable}
            ref={(e) => {
              e?.scrollTo({ left: 99999 });
            }}
          >
            <table className="table table-bordered table-sm table-hover">
              <thead>
                <tr>
                  <th>Кто</th>
                  <th>Кому</th>
                  <th>Когда</th>
                  <th>Комментарий</th>
                  <th>Сколько</th>
                  {!frozen && canEdit && <th>&nbsp;</th>}
                </tr>
              </thead>
              <tbody>
                {payments
                  .toSorted((a, b) => a.date.getTime() - b.date.getTime())
                  .map((payment) => {
                    return (
                      <tr key={payment.id}>
                        <td>
                          {payment.userFrom
                            ? [payment.userFrom.name, payment.userFrom.surname].join('\u00a0')
                            : payment.fundFrom?.name}
                        </td>
                        <td>
                          {payment.userTo ? (
                            [payment.userTo.name, payment.userTo.surname].join('\u00a0')
                          ) : (
                            <span>
                              <Link to={`/finances/funds/${payment.fundTo!.id}`}>
                                {payment.fundTo?.name}
                              </Link>
                            </span>
                          )}
                        </td>
                        <td title={'Added: ' + payment.dateCreate.toLocaleString()}>
                          {payment.date.toLocaleDateString()}
                        </td>
                        <td>{payment.comment}</td>
                        <td className="text-end">
                          {!!payment.totalInCurrency && (
                            <small className="text-info">
                              {formatFinance(payment.totalInCurrency, 0, payment.currency?.symbol)}
                              &thinsp;×&thinsp;{round(payment.total / payment.totalInCurrency, 2)}
                              &thinsp;=&thinsp;
                            </small>
                          )}
                          {formatFinance(payment.total)}
                        </td>
                        {!frozen && canEdit && (
                          <td className="text-end">
                            <PohButton
                              icon={IconsEnum.trash}
                              size={ButtonSize.Small}
                              onClick={() => handleDeletePayment(payment)}
                            />
                            <PohButton
                              icon={IconsEnum.edit}
                              size={ButtonSize.Small}
                              onClick={() => handleEditPayment(payment)}
                              className="ms-2"
                            />
                          </td>
                        )}
                      </tr>
                    );
                  })}
              </tbody>
            </table>
          </div>
        )}

        <h4 className="mt-4">Итого</h4>
        <div
          className={styles.finTable}
          ref={(e) => {
            e?.scrollTo({ left: 99999 });
          }}
        >
          <table className="table table-bordered table-sm table-hover">
            <thead>
              <tr>
                <th>Участник</th>
                <th>Затраты</th>
                <th>Взнос отпр.</th>
                <th>Взнос получ.</th>
                <th>Всего долг</th>
                <th>Остаток долга</th>
              </tr>
            </thead>
            <tbody>
              {hikingData.hikers.map((hiker) => {
                const idUser = hiker.idUser;

                const userExpenses = hikerTotalExpenses[idUser] ?? 0;
                const userPayments = hikerTotalPayments[idUser] ?? 0;
                const userFundsPayments = hikerTotalFundsPayments[idUser] ?? 0;
                const userIncomePayments = hikerTotalIncomePayments[idUser] ?? 0;
                const userRate = hikerRates[idUser] ?? 1;

                const userDebt = Math.ceil(hikerDebt[idUser] ?? 0);
                const restDebt = userDebt - (userExpenses + userPayments - userIncomePayments);
                const userDebtInfo = hikerDebtInfo[idUser] ?? [];

                const userRest = userExpenses - userIncomePayments;
                const userPlus =
                  Math.abs(restDebt) <= hikingData.hikers.length && userIncomePayments
                    ? userDebt - userRest - userPayments
                    : 0;

                const roundedRestDebt = Math.round(restDebt - userPlus);

                const resClassNames = clsx({
                  'text-end': roundedRestDebt !== 0,
                  'text-success': roundedRestDebt === 0,
                  'bg-danger': roundedRestDebt > 0,
                  'bg-success': roundedRestDebt < 0,
                });

                return (
                  <tr
                    key={idUser}
                    className={clsx(userDebt === 0 && 'text-muted')}
                    style={{ opacity: userDebt === 0 ? 0.5 : 1 }}
                  >
                    <td>
                      <span
                        onClick={() =>
                          showModal({
                            size: 'lg',
                            title: `Долг участника: ${[hiker.name, hiker.surname].join('\u00a0')}`,
                            children: (
                              <>
                                <p>Из чего сформирована сумма долга</p>
                                <table className="table table-bordered table-sm table-hover">
                                  <thead>
                                    <tr>
                                      <th>Чек</th>
                                      <th>Сумма</th>
                                      <th>Комментарий</th>
                                    </tr>
                                  </thead>
                                  <tbody>
                                    {userDebtInfo.map((u, i) => {
                                      return (
                                        <tr key={`${i}_${u.total}`}>
                                          <td>
                                            {u.receipt.name} на сумму{' '}
                                            {formatFinance(u.receipt.total)} от{' '}
                                            {u.receipt.date.toLocaleString()} {u.receipt.user.name}{' '}
                                            {u.receipt.user.surname}
                                          </td>
                                          <td className="text-end">{formatFinance(u.total)}</td>
                                          <td>
                                            {u.type === 'equally' &&
                                              `Сумма чека поровну поделена на всех. ${u.comment}`}
                                            {u.type === 'rate' &&
                                              `Сумма чека поровну поделена на всех и умножена на коэффициент неполного участия ${round(userRate * 100)}%. ${u.comment ?? ''}`}
                                            {u.type === 'participation' &&
                                              `Сумма чека поделена на ${u.receipt.participation?.length}. ${u.comment ?? ''}`}
                                          </td>
                                        </tr>
                                      );
                                    })}
                                  </tbody>
                                  <tfoot>
                                    <tr>
                                      <th>Итого:</th>
                                      <th className="text-end text-danger">
                                        {formatFinance(
                                          Math.ceil(
                                            userDebtInfo.reduce((sum, { total }) => sum + total, 0),
                                          ),
                                        )}
                                      </th>
                                      <th></th>
                                    </tr>
                                  </tfoot>
                                </table>
                              </>
                            ),
                          })
                        }
                      >
                        {[hiker.name, hiker.surname].join('\u00a0')}
                      </span>
                      {userRate !== 1 && (
                        <sup
                          className="text-danger"
                          title={`
                        Неполное участие в походе
                        c ${hiker.dateFrom ? hiker.dateFrom.toLocaleString() : 'начала'}
                        до ${hiker.dateTo ? hiker.dateTo.toLocaleString() : 'конца'}
                      `}
                          onClick={() => {
                            const pct = round(userRate * 100, 0);
                            const pctBefore = hiker.dateFrom ? 100 - pct : 0;
                            const pctAfter = hiker.dateTo ? 100 - pct : 0;

                            confirmModal({
                              title: 'Неполное участие в походе',
                              children: (
                                <div>
                                  {[hiker.name, hiker.surname].join('\u00a0')} участвует в походе c{' '}
                                  {hiker.dateFrom ? hiker.dateFrom.toLocaleString() : 'начала'}
                                  &nbsp; до {hiker.dateTo ? hiker.dateTo.toLocaleString() : 'конца'}
                                  .
                                  <div className="progress mt-2 mb-4">
                                    <div
                                      className="progress-bar bg-danger"
                                      role="progressbar"
                                      style={{ width: `${pctBefore}%` }}
                                      aria-valuenow={pctBefore}
                                      aria-valuemin={0}
                                      aria-valuemax={100}
                                    />
                                    <div
                                      className="progress-bar bg-success"
                                      role="progressbar"
                                      style={{ width: `${pct}%` }}
                                      aria-valuenow={pct}
                                      aria-valuemin={0}
                                      aria-valuemax={100}
                                    />
                                    <div
                                      className="progress-bar progress-bar-striped bg-danger"
                                      role="progressbar"
                                      style={{ width: `${pctAfter}%` }}
                                      aria-valuenow={pctAfter}
                                      aria-valuemin={0}
                                      aria-valuemax={100}
                                    />
                                  </div>
                                  Что составляет <b className="text-success">{pct}%</b> от всего
                                  похода. Этот коэффициент используется, в том числе, для расчета
                                  доли затрат.
                                </div>
                              ),
                            });
                          }}
                        >
                          <b> {round(userRate * 100, 0)}%</b>
                        </sup>
                      )}
                    </td>
                    <td className="text-end">{formatFinance(userExpenses)}</td>
                    <td className="text-end">{formatFinance(userPayments + userFundsPayments)}</td>
                    <td className="text-end">{formatFinance(userIncomePayments)}</td>
                    <td className="text-end">{formatFinance(userDebt)}</td>
                    <td className={resClassNames}>
                      {roundedRestDebt === 0 ? '✅ в расчете' : formatFinance(restDebt, 0)}
                      {roundedRestDebt === 0 && userPlus > 0 && (
                        <sup
                          onClick={() =>
                            showModal({
                              title: 'Про округления',
                              size: 'lg',
                              children: (
                                <div>
                                  <p>
                                    С целью упрощения расчетов суммы в столбце долг округляются до
                                    целого рубля в большую сторону.
                                  </p>
                                  <p>Это бонус для человека, который тратил и собирал деньги.</p>
                                  <table className="table table-bordered table-sm table-hover">
                                    <thead>
                                      <tr>
                                        <th>Участник</th>
                                        <th>Долг</th>
                                        <th>Реальный долг</th>
                                        <th>Переплата</th>
                                      </tr>
                                    </thead>
                                    <tbody>
                                      {hikingData.hikers.map((hiker1) => {
                                        const debt = hikerDebt[hiker1.idUser] ?? 0;
                                        return (
                                          <tr key={hiker1.idUser}>
                                            <td>{[hiker1.name, hiker1.surname].join('\u00a0')}</td>
                                            <td className="text-end">
                                              {formatFinance(Math.ceil(debt))}
                                            </td>
                                            <td className="text-end">{formatFinance(debt)}</td>
                                            <td className="text-end">
                                              {formatFinance(Math.ceil(debt) - debt)}
                                            </td>
                                          </tr>
                                        );
                                      })}
                                    </tbody>
                                  </table>
                                </div>
                              ),
                            })
                          }
                          title={`Сумма полученная в результате округления долга до полного рубля.`}
                        >
                          +{formatFinance(userPlus)}
                        </sup>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </PohContainer>
    </div>
  );
};

export default HikingFinancesPage;
