import React from 'react';

import { post } from '@helpers/httpClient';
import notificationHelper from '@helpers/notificationHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';

import FinanceReceiptHTML from './FinanceReceiptHTML';

interface IIFnsReceiptDataItem {
  name: string;
  price: number;
  quantity: number;
  itemsQuantityMeasure: number;
  sum: number;
}
interface IFnsReceiptData {
  dateTime: string;
  totalSum: number;
  items: IIFnsReceiptDataItem[];
  retailPlace: string;
  user: string;
  retailPlaceAddress: string;
  html: string | null;
  url: string | null;
  qr_code: string | null;
}
interface IQRCoderFromReceiptProps {
  onData: (data: IFnsReceiptData | null) => void;
  pdf_url: string | null;
  qr_code: string | null;
  html: string | null;
}

const QRCoderFromReceipt: React.FC<IQRCoderFromReceiptProps> = ({
  onData,
  pdf_url,
  qr_code,
  html,
}) => {
  const [res, setRes] = React.useState<string | null>(null);
  const [facingMode, setFacingMode] = React.useState<'environment' | 'user'>('environment');
  const videoRef = React.useRef<HTMLVideoElement>(null);
  const streamRef = React.useRef<MediaStream>(null);

  React.useEffect(() => {
    const start = async () => {
      if (!videoRef.current) return;
      streamRef.current = await navigator.mediaDevices.getUserMedia({ video: { facingMode } });
      videoRef.current.srcObject = streamRef.current;
      videoRef.current.play();
    };

    start();

    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach((t) => t.stop());
        streamRef.current = null;
      }
    };
  }, [res]);

  if (html)
    return (
      <div>
        <PohButton onClick={() => onData(null)}>x</PohButton>
        {pdf_url && (
          <a href={pdf_url} target="_blank" rel="noreferrer">
            pdf
          </a>
        )}
        {qr_code && <small title={qr_code}>qr</small>}
        <FinanceReceiptHTML html={html} />
      </div>
    );

  return (
    <div>
      {!res && (
        <>
          <video
            ref={videoRef}
            playsInline
            width="100%"
            onLoadedMetadata={(e) => {
              const video = e.target as HTMLVideoElement;
              // eslint-disable-next-line @typescript-eslint/ban-ts-comment
              //@ts-expect-error
              const barcodeDetector = new BarcodeDetector({ formats: ['qr_code'] });
              const canvas = document.createElement('canvas');
              canvas.width = video.videoWidth;
              canvas.height = video.videoHeight;

              const context = canvas.getContext('2d');

              const checkForQrCode = async function () {
                context!.drawImage(video, 0, 0, canvas.width, canvas.height);
                const barcodes = await barcodeDetector.detect(canvas);

                if (barcodes.length > 0) {
                  const barcodeData = barcodes[0].rawValue;
                  setRes(barcodeData);
                } else {
                  requestAnimationFrame(checkForQrCode);
                }
              };

              checkForQrCode();
            }}
          />
          <PohButton
            block
            onClick={() => setFacingMode((cur) => (cur === 'user' ? 'environment' : 'user'))}
          >
            Переключить камеру
          </PohButton>
          <input
            type="text"
            className="w-100"
            placeholder="Вставить изображение с QR-кодом из буфера обмена"
            onPaste={async (ev) => {
              if (!ev.clipboardData?.items?.length) return;
              const { items } = ev.clipboardData;
              for (const item of items) {
                if (!item.type.startsWith('image/')) continue;
                const file = item.getAsFile()!;
                const bitmap = await createImageBitmap(file);

                // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                //@ts-expect-error
                const barcodeDetector = new BarcodeDetector({ formats: ['qr_code'] });
                const canvas = document.createElement('canvas');
                canvas.width = bitmap.width;
                canvas.height = bitmap.height;

                const context = canvas.getContext('2d');

                context!.drawImage(bitmap, 0, 0, bitmap.width, bitmap.height);
                const barcodes = await barcodeDetector.detect(canvas);

                if (barcodes.length > 0) {
                  const barcodeData = barcodes[0].rawValue;
                  setRes(barcodeData);
                } else {
                  notificationHelper.warn('QR-кодов не найдено');
                }
              }
            }}
          />
        </>
      )}
      {res && (
        <div className="d-flex flex-column" style={{ gap: 8 }}>
          {res && (
            <>
              <PohButton
                variant={ButtonVariant.Secondary}
                onClick={() => {
                  setRes(null);
                }}
              >
                Отмена
              </PohButton>
              <PohButton
                variant={ButtonVariant.Success}
                onClick={async () => {
                  try {
                    const qp = new URLSearchParams(res);
                    const d = {
                      //t=20260430T1935&s=79.99&fn=7380440801805052&i=81489&fp=896838332&n=1

                      fn: qp.get('fn'), //ФН
                      fd: qp.get('i'), //ФД
                      fp: qp.get('fp'), //ФП
                      t: qp.get('t'), //время с чека
                      n: qp.get('n'), //вид кассового чека
                      s: qp.get('s'), //сумма чека
                      qr: 1, //признак сканирования QR-кода
                    };
                    const e = await post('/ajax/hiking/finance/proverkacheka.php', d);

                    if (e.error) {
                      throw new Error(e.error?.data ?? e.error);
                    }

                    if (e.data.json)
                      onData({
                        ...e.data.json,
                        html: e.data.html ?? null,
                        url: e.data.pdfurl ?? null,
                        qr_code: res,
                      } as IFnsReceiptData);
                  } catch (error) {
                    notificationHelper.error((error as Error).message);
                  }
                }}
              >
                Запросить в ФНС
              </PohButton>
            </>
          )}
        </div>
      )}
    </div>
  );
};

export default QRCoderFromReceipt;
