import React, { FormEvent } from 'react';

import FileImage from '@pohodnik/icons/svg/Files/FileImage';

import { importHikingFinancesReceiptItems } from '@apps/Hiking/@services/hikingFinancesReceiptItems.service';
import HelpInfo from '@components/HelpInfo';
import { declOfNum } from '@helpers/formatHelper';
import { round } from '@helpers/mathHelper';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohImageUploader from '@ui-kit/ImageUploader';
import PohInput, { InputSizes, InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import { confirmModal2 } from '@ui-kit/Modal/modalsHelper';
import PohSelect from '@ui-kit/Select';

import QRCoderFromReceipt from './QRCoderFromReceipt';
import ReceiptItems from './ReceiptItems';
import QRIcon from '../../../../img/svg/qr.inline.svg';
import {
  addOrUpdateHikingFinancesReceipt,
  getHikingFinanceCurrencies,
} from '../../@services/hikingFinances.service';
import { IHikingData } from '../../@types/hiking.types';
import {
  IHikingFinanceCurrency,
  IHikingReceipt,
  IHikingReceiptCategory,
} from '../../@types/hikingFinances.types';

export interface IEditReceiptModalProps {
  receipt: IHikingReceipt;
  onAdd?: (selected: IHikingReceipt) => void;
  onEdit?: (selected: IHikingReceipt) => void;
  hikingData: IHikingData;
  categories: IHikingReceiptCategory[];
}

const EditReceiptModal: React.FC<IEditReceiptModalProps> = ({
  receipt,
  hikingData,
  categories,
  onAdd,
  onEdit,
}) => {
  const [currencyRate, setCurrencyRate] = React.useState(
    receipt.totalInCurrency ? (receipt.total / receipt.totalInCurrency).toString() : '',
  );
  const [isCurrencyMode, setIsCurrencyMode] = React.useState(!!receipt.currency);
  const [currencies, setCurrencies] = React.useState<IHikingFinanceCurrency[]>([]);
  const [editData, setEditData] = React.useState<IHikingReceipt>(receipt);
  const [isSaving, setIsSaving] = React.useState(false);
  const [err, setErr] = React.useState<Error>();
  const [proofMode, setProofMode] = React.useState<'img' | 'qr' | 'url'>('img');

  const [imageAsUrl] = React.useState(false);

  React.useEffect(() => {
    getHikingFinanceCurrencies().then(setCurrencies);
  }, []);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    try {
      setErr(undefined);
      setIsSaving(true);

      const addedOrUpdatedReceipt = await addOrUpdateHikingFinancesReceipt(editData, hikingData.id);

      if (receipt.id > 0) {
        onEdit?.(addedOrUpdatedReceipt);
      } else {
        onAdd?.(addedOrUpdatedReceipt);
      }
    } catch (er) {
      setErr(er as Error);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="vertical-gapped">
      <PohRow className="mb-2">
        <PohCol sm={8} className="vertical-gapped">
          {isCurrencyMode && (
            <div className="d-flex align-items-end horizontal-gapped">
              <PohInput
                type={InputTypes.number}
                name="totalInCurrency"
                autoFocus={isCurrencyMode}
                min={0}
                disabled={isSaving}
                value={editData.totalInCurrency ? editData.totalInCurrency.toString() : ''}
                onChange={(value) => {
                  setEditData((cur) => ({
                    ...cur,
                    totalInCurrency: +value,
                    //total: currencyRate.length ? round(+value * +currencyRate, 2) : cur.total
                  }));
                  if (editData.total && value) {
                    setCurrencyRate((editData.total / +value).toString());
                  }
                }}
                className="form-control"
                required
                labelClassName="w-100"
                placeholder="Сколько потрачено"
                wrapperClassName="flex-grow-1"
                label="Сумма в валюте"
              />
              <PohSelect
                name="currency"
                options={currencies
                  .filter((f) => f.id > 1)
                  .map((x) => ({ value: x.id, label: x.symbol }))}
                value={editData.currency?.id}
                onChange={(value) => {
                  setEditData((cur) => ({
                    ...cur,
                    currency:
                      value && value > 1 ? (currencies.find((c) => c.id === +value) ?? null) : null,
                  }));
                }}
                style={{ width: 64, marginTop: -2, marginLeft: 2 }}
                className="form-control"
                required
                disabled={isSaving}
                placeholder="Rub"
              />
              <PohButton
                icon={IconsEnum.trash}
                tabIndex={-1}
                onClick={() => {
                  setEditData((cur) => ({ ...cur, totalInCurrency: null, currency: null }));
                  setIsCurrencyMode((c) => !c);
                }}
              />
            </div>
          )}
          <div className="d-flex vertical-gapped">
            <PohInput
              type={InputTypes.number}
              name="total"
              autoFocus={!isCurrencyMode}
              min={0}
              disabled={isSaving}
              value={editData.total ? editData.total.toString() : ''}
              onChange={(value) => {
                setEditData((cur) => ({ ...cur, total: +value }));
                if (editData.totalInCurrency && value) {
                  setCurrencyRate((+value / editData.totalInCurrency).toString());
                }
              }}
              className="form-control"
              required
              label={
                <div className="d-flex justify-content-between">
                  Сумма в рублях
                  <small>
                    {!isCurrencyMode && (
                      <a
                        href="#"
                        onClick={(e) => {
                          e.preventDefault();
                          setIsCurrencyMode((c) => !c);
                          setEditData((cur) => ({
                            ...cur,
                            totalInCurrency: null,
                            currency: currencies[1],
                          }));
                        }}
                      >
                        другая валюта
                      </a>
                    )}
                  </small>
                </div>
              }
              labelClassName=" w-100"
              wrapperClassName="w-100"
              placeholder="Сколько потрачено"
            />
            {isCurrencyMode && (
              <PohInput
                type={InputTypes.number}
                name="currencyRate"
                min={0.1}
                step={0.001}
                disabled={isSaving}
                value={currencyRate}
                onChange={(value) => {
                  setCurrencyRate(value);
                  if (value && editData.totalInCurrency) {
                    setEditData((cur) => ({
                      ...cur,
                      total: round(editData.totalInCurrency! * +value, 2),
                    }));
                  }
                }}
                className="form-control"
                wrapperClassName="ms-1"
                required
                label={`По курсу (₽ за 1 ${editData.currency?.symbol})`}
              />
            )}
          </div>
          <PohInput
            name="name"
            value={editData.name}
            onChange={(value) => setEditData((cur) => ({ ...cur, name: value }))}
            className="form-control"
            required
            disabled={isSaving}
            label="Название"
            placeholder="На что было потрачено"
            wrapperClassName=""
          />
          <PohSelect<number>
            name="category"
            options={categories.map((x) => ({ value: x.id, label: x.name }))}
            value={editData.idCategory}
            onChange={(value: any) =>
              setEditData((cur) => ({ ...cur, idCategory: value ? +value : null }))
            }
            className="form-control"
            disabled={isSaving}
            allowEmpty
            labelClassName="w-100"
            label={
              <div>
                <HelpInfo className="float-end">
                  <table className="table table-sm table-bordered table-striped">
                    <tbody>
                      {categories.map((c) => (
                        <tr key={c.id}>
                          <td>
                            <small>{c.name}</small>
                          </td>
                          <td>
                            <small>
                              <em>{c.comment}</em>
                            </small>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </HelpInfo>
                Категория (можно не указывать){' '}
              </div>
            }
            placeholder="Категория"
          />
          <div className=" d-flex">
            {editData.user.id !== editData.author.id && (
              <div className="ms-auto mt-2 d-inline-flex align-items-center">
                <PohAva className="me-2" src={editData.user.photo} alt={editData.user.name} />
                <div>
                  {editData.user.name}
                  <br />
                  {editData.user.surname}
                </div>
              </div>
            )}
          </div>
          {receipt.id > 0 && <ReceiptItems id_hiking={hikingData.id} id_receipt={receipt.id} />}
        </PohCol>
        <PohCol sm={4}>
          <div
            className="form-label d-flex justify-content-between align-items-center"
            style={{ margin: 0, lineHeight: 1 }}
          >
            Чек
            <aside className="horizontal-gapped">
              {proofMode !== 'img' && (
                <PohButton
                  icon
                  size={ButtonSize.Small}
                  onClick={(e) => {
                    e.altKey ? setProofMode('url') : setProofMode('img');
                  }}
                  title="Изображение чека"
                  variant={ButtonVariant.Light}
                >
                  <FileImage />
                </PohButton>
              )}
              {proofMode !== 'qr' && 'BarcodeDetector' in globalThis && (
                <PohButton
                  icon
                  size={ButtonSize.Small}
                  title="Сканировать чек (QR-код)"
                  onClick={() => {
                    setProofMode('qr');
                  }}
                >
                  <QRIcon />
                </PohButton>
              )}
            </aside>
          </div>
          <div style={{ maxHeight: 480, overflow: 'auto' }}>
            {proofMode === 'qr' && (
              <QRCoderFromReceipt
                pdf_url={editData.pdf_url}
                html={editData.html}
                qr_code={editData.qr_code}
                onData={async (d) => {
                  setEditData((cur) =>
                    d
                      ? {
                          ...(cur as IHikingReceipt),
                          total: Math.floor(d.totalSum / 100),
                          date: new Date(d.dateTime),
                          name: d.user,
                          pdf_url: d?.url,
                          html: d?.html,
                          qr_code: d?.qr_code,
                          images: { orig: null, [600]: null, [100]: null },
                        }
                      : { ...cur, html: null, pdf_url: null, qr_code: null },
                  );

                  if (
                    d?.items.length &&
                    (await confirmModal2(
                      <div className="text-center">
                        <strong>
                          В чеке указано {d.items.length}{' '}
                          {declOfNum(d.items.length, ['позицию', 'позиции', 'позиций'])}.
                        </strong>
                        <br />
                        Добавить их автоматически?
                        <br />
                        <small className="text-muted">
                          Можно будет удалить или отредактировать <br /> их после добавления
                        </small>
                      </div>,
                    ))
                  ) {
                    try {
                      setErr(undefined);
                      setIsSaving(true);

                      const addedOrUpdatedReceipt = await addOrUpdateHikingFinancesReceipt(
                        {
                          ...editData,
                          total: Math.floor(d.totalSum / 100),
                          date: new Date(d.dateTime),
                          name: d.user,
                          pdf_url: d?.url,
                          html: d?.html,
                          qr_code: d?.qr_code,
                          images: { orig: null, [600]: null, [100]: null },
                        },
                        hikingData.id,
                      );

                      const addedItemsCount = await importHikingFinancesReceiptItems(
                        d.items.map((x) => ({
                          name: x.name,
                          cost: x.price / 100,
                          amount: x.quantity,
                        })),
                        addedOrUpdatedReceipt.id,
                        hikingData.id,
                      );

                      notificationHelper.success(
                        `Автоматически импортировано из чека позиций: ${addedItemsCount}`,
                      );

                      if (receipt.id > 0) {
                        onEdit?.(addedOrUpdatedReceipt);
                      } else {
                        onAdd?.(addedOrUpdatedReceipt);
                      }
                    } catch (er) {
                      setErr(er as Error);
                    } finally {
                      setIsSaving(false);
                    }
                  }
                }}
              />
            )}
            {proofMode === 'img' && (
              <PohImageUploader
                folder="images/receipts"
                name={`hiking${hikingData.id}_user${editData.user.id}_${new Date().toString().replace(/[^\da-zA-Z]+/g, '')}`}
                validation={{ maxHeight: 99999, maxWidth: 5555, size: 10024288 }}
                sizes={[100, 600]}
                src={editData.images.orig ?? ''}
                onChange={(src, res) => {
                  setEditData((cur) => ({
                    ...cur,
                    images: {
                      orig: src ?? '',
                      [100]: res?.sizes?.[100] ?? '',
                      [600]: res?.sizes?.[600] ?? '',
                    },
                  }));
                }}
              />
            )}
            {(proofMode === 'url' || proofMode === 'img') && (
              <PohInput
                required
                name="image"
                size={InputSizes.Small}
                type={InputTypes.url}
                value={editData.images.orig ?? ''}
                onChange={(v) => {
                  setEditData((cur) => ({
                    ...cur,
                    images: {
                      orig: v || null,
                      [100]: v || null,
                      [600]: v || null,
                    },
                  }));
                }}
                style={
                  proofMode === 'url'
                    ? {}
                    : {
                        height: 1,
                        width: 1,
                        opacity: 0.00001,
                        marginLeft: '50%',
                      }
                }
              />
            )}
          </div>

          <input
            required
            name="image"
            value={editData.images.orig ?? ''}
            onChange={(e) => {
              setEditData((cur) => ({
                ...cur,
                images: {
                  orig: e.target.value ?? '',
                  [100]: e.target.value ?? '',
                  [600]: e.target.value ?? '',
                },
              }));
            }}
            style={
              imageAsUrl
                ? {}
                : {
                    height: 1,
                    width: 1,
                    opacity: 0.00001,
                    marginLeft: '50%',
                  }
            }
          />
        </PohCol>
      </PohRow>
      <footer className="text-end">
        {err && <PohAlert>{err.message}</PohAlert>}
        <button type="submit" className="btn btn-primary mt-3 ms-auto" disabled={isSaving}>
          {editData.id > 0 ? 'Сохранить' : 'Добавить'}
        </button>
      </footer>
    </form>
  );
};

export default EditReceiptModal;
