import React, { FormEvent, useState } from 'react';

import { selectFundInModalAsync } from '@apps/Finances/components/FundSelect';
import HikerSelectInput from '@apps/Hiking/@components/HikerSelectInput';
import { mapHikerToUser, mapUserToHiker } from '@apps/Hiking/@mappers/hiking.mapper';
import { getInputDate, getSQLDate } from '@helpers/dateHelper';
import { round } from '@helpers/mathHelper';
import { err } from '@helpers/notificationHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohSelect from '@ui-kit/Select';

import {
  addOrEditHikingFinancePayment,
  getHikingFinanceCurrencies,
} from '../../@services/hikingFinances.service';
import { IHikingData } from '../../@types/hiking.types';
import {
  IHikingFinanceCurrency,
  IHikingFinancePaymentAddOrUpdateDTO,
  IHikingPayment,
} from '../../@types/hikingFinances.types';

interface IEditPaymentModalProps {
  hikingData: IHikingData;
  payment: IHikingPayment;
  onCancel: () => void;
  onSave: (payment: IHikingPayment) => void;
}

const EditPaymentModal: React.FC<IEditPaymentModalProps> = ({
  onSave,
  onCancel,
  payment,
  hikingData,
}) => {
  const [currencyRate, setCurrencyRate] = React.useState(
    payment.totalInCurrency ? (payment.total / payment.totalInCurrency).toString() : '',
  );

  const [isCurrencyMode, setIsCurrencyMode] = React.useState(!!payment.currency);
  const [currencies, setCurrencies] = React.useState<IHikingFinanceCurrency[]>([]);

  const [isFromFund, setIsFromFund] = React.useState(!!payment.fundFrom);
  const [isToFund, setIsToFund] = React.useState(!!payment.fundTo);

  React.useEffect(() => {
    getHikingFinanceCurrencies().then(setCurrencies);
  }, []);

  const [editData, setEditData] = useState<IHikingPayment>(payment);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();

    // if (editData.userFrom.id === editData.userTo.id) {
    //   err('Нельзя самому себе')
    //   return;
    // }

    if (!(editData.total > 0)) {
      err('Нельзя 0');
      return;
    }
    try {
      setLoading(true);
      const data: IHikingFinancePaymentAddOrUpdateDTO = {
        id_user: editData?.userFrom?.id ?? null,
        id_target_user: editData?.userTo?.id ?? null,
        id_finance_fund: editData?.fundFrom?.id ?? null,
        id_target_finance_fund: editData?.fundTo?.id ?? null,
        summ: editData.total,
        id_hiking: hikingData.id,
        comment: editData.comment || '',
        date: getSQLDate(editData.date),
        summ_in_currency: editData.totalInCurrency ? editData.totalInCurrency : null,
        id_currency: editData.currency ? editData.currency.id : null,
      };

      if (editData.id > 0) {
        data.id = editData.id;
      }

      const { success, id } = await addOrEditHikingFinancePayment(data);
      success &&
        onSave({
          ...payment,
          ...editData,
          id,
        });
    } catch (e1) {
      err((e1 as Error).message);
    } finally {
      setLoading(false);
    }
  };

  const handleChange =
    <k extends keyof IHikingPayment>(fieldName: k) =>
    (value: IHikingPayment[k]) =>
      setEditData((cur) => ({ ...cur, [fieldName]: value }));

  return (
    <form onSubmit={handleSubmit} className="vertical-gapped">
      <PohRow>
        <PohCol xs={6}>
          {!isFromFund ? (
            <HikerSelectInput
              id_hiking={hikingData.id}
              labelClassName="w-100"
              label={
                <div className="d-flex w-100 justify-content-between">
                  Кто зачислил
                  <a
                    href="#"
                    onClick={(e) => {
                      e.preventDefault();
                      setIsFromFund(true);
                      handleChange('userFrom')(null);
                    }}
                  >
                    участник
                  </a>
                </div>
              }
              placeholder="Отправитель"
              value={editData.userFrom ? mapUserToHiker(editData.userFrom) : null}
              disabled={loading}
              onChange={(h) => handleChange('userFrom')(mapHikerToUser(h))}
              required
            />
          ) : (
            <PohInput
              readOnly
              onKeyDown={(e) => e.preventDefault()}
              labelClassName="w-100"
              label={
                <div className="d-flex w-100 justify-content-between">
                  Кто зачислил
                  <a
                    href="#"
                    onClick={(e) => {
                      e.preventDefault();
                      setIsFromFund(false);
                      handleChange('fundFrom')(null);
                    }}
                  >
                    фонд
                  </a>
                </div>
              }
              placeholder="Фонд-Отправитель"
              value={editData.fundFrom ? editData.fundFrom.name : ''}
              disabled={loading}
              onClick={async () => {
                const fund = await selectFundInModalAsync({ is_active: 1 });
                handleChange('fundFrom')(fund);
              }}
              required
            />
          )}
        </PohCol>
        <PohCol xs={6}>
          {!isToFund ? (
            <HikerSelectInput
              id_hiking={hikingData.id}
              labelClassName="w-100"
              label={
                <div className="d-flex w-100 justify-content-between">
                  Кому зачислил
                  <a
                    href="#"
                    onClick={(e) => {
                      e.preventDefault();
                      setIsToFund(true);
                      handleChange('userTo')(null);
                    }}
                  >
                    участник
                  </a>
                </div>
              }
              value={editData.userTo ? mapUserToHiker(editData.userTo) : null}
              disabled={loading}
              placeholder="Получатель"
              onChange={(h) => handleChange('userTo')(mapHikerToUser(h))}
              required
            />
          ) : (
            <PohInput
              onKeyDown={(e) => e.preventDefault()}
              labelClassName="w-100"
              label={
                <div className="d-flex w-100 justify-content-between">
                  Кому зачислил
                  <a
                    href="#"
                    onClick={(e) => {
                      e.preventDefault();
                      setIsToFund(false);
                      handleChange('fundTo')(null);
                    }}
                  >
                    фонд
                  </a>
                </div>
              }
              placeholder="Фонд-Получатель"
              value={editData.fundTo ? editData.fundTo.name : ''}
              disabled={loading}
              onClick={async () => {
                const fund = await selectFundInModalAsync({ is_active: 1 });
                handleChange('fundTo')(fund);
              }}
              required
            />
          )}
        </PohCol>
      </PohRow>
      {isCurrencyMode && (
        <PohRow className="mb-2">
          <PohCol sm={12} className="d-flex align-items-center">
            <PohInput
              type={InputTypes.number}
              name="totalInCurrency"
              autoFocus={isCurrencyMode}
              label="Сумма в валюте"
              min={0}
              value={editData.totalInCurrency ? editData.totalInCurrency.toString() : ''}
              onChange={(value) => {
                setEditData((cur) => ({
                  ...cur,
                  totalInCurrency: +value,
                  //total: currencyRate.length ? round(+value * +currencyRate, 2) : cur.total
                }));
                if (editData.total && value) {
                  setCurrencyRate(round(editData.total / +value, 2).toString());
                }
              }}
              className="form-control"
              required
              placeholder="Сколько зачислено"
            />
            <PohSelect
              name="currency"
              options={currencies
                .filter((f) => f.id > 1)
                .map((x) => ({ value: x.id, label: x.symbol }))}
              value={editData.currency?.id}
              onChange={(value) => {
                setEditData((cur) => ({
                  ...cur,
                  currency:
                    value && value > 1 ? (currencies.find((c) => c.id === +value) ?? null) : null,
                }));
              }}
              style={{ width: 64, marginTop: -2, marginLeft: 2 }}
              className="form-control"
              required
            />
            <PohButton
              icon={IconsEnum.trash}
              tabIndex={-1}
              onClick={() => {
                setEditData((cur) => ({ ...cur, totalInCurrency: null, currency: null }));
                setIsCurrencyMode((c) => !c);
              }}
            />
          </PohCol>
        </PohRow>
      )}
      <PohRow className="mb-2">
        <PohCol sm={isCurrencyMode ? 6 : 12} className="d-flex">
          <PohInput
            type={InputTypes.number}
            step={0.01}
            value={editData.total.toString()}
            onChange={(value) => {
              setEditData((cur) => ({ ...cur, total: parseFloat(value) }));
              if (editData.totalInCurrency && value) {
                setCurrencyRate((+value / editData.totalInCurrency).toString());
              }
            }}
            disabled={loading}
            required
            label={
              <div className="d-flex justify-content-between">
                Сумма в рублях
                <small>
                  {!isCurrencyMode && (
                    <a
                      href="#"
                      onClick={(e) => {
                        e.preventDefault();
                        setIsCurrencyMode((c) => !c);
                        setEditData((cur) => ({
                          ...cur,
                          totalInCurrency: null,
                          currency: currencies[1],
                        }));
                      }}
                    >
                      другая валюта
                    </a>
                  )}
                </small>
              </div>
            }
            labelClassName="w-100"
            wrapperClassName="w-100"
            min={0}
          />
        </PohCol>
        {isCurrencyMode && (
          <PohCol sm={6}>
            <PohInput
              type={InputTypes.number}
              name="currencyRate"
              min={0.1}
              step={0.001}
              disabled={loading}
              value={currencyRate}
              onChange={(value) => {
                setCurrencyRate(value);
                if (value && editData.totalInCurrency) {
                  setEditData((cur) => ({
                    ...cur,
                    total: round(editData.totalInCurrency! * +value, 2),
                  }));
                }
              }}
              className="form-control"
              wrapperClassName="ms-1"
              required
              label={`По курсу (₽ за 1 ${editData.currency?.symbol})`}
            />
          </PohCol>
        )}
      </PohRow>
      <PohInput
        horizontal
        type={InputTypes.date}
        label="Дата"
        value={editData.date ? getInputDate(new Date(editData.date)).substr(0, 10) : ''}
        onChange={(value) => setEditData((cur) => ({ ...cur, date: new Date(value) }))}
        labelGrid={3}
        inputGrid={9}
        disabled={loading}
      />
      <PohInput
        horizontal
        labelGrid={3}
        inputGrid={9}
        label="Комментарий"
        placeholder="Можно не заполнять"
        value={editData?.comment}
        onChange={(value) => setEditData((cur) => ({ ...cur, comment: value }))}
        disabled={loading}
      />
      <footer className="text-end mt-4">
        <PohButton
          disabled={loading}
          variant={ButtonVariant.Secondary}
          onClick={onCancel}
          className="me-2"
        >
          Отмена
        </PohButton>
        <PohButton type="submit" disabled={loading} variant={ButtonVariant.Primary}>
          {payment.id > 0 ? 'Сохранить' : 'Добавить'}
        </PohButton>
      </footer>
    </form>
  );
};

export default EditPaymentModal;
