import React from 'react';

import PohAlert from '@ui-kit/Alert';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohList from '@ui-kit/List';

import { updateHikingFinancesReceiptParticipation } from '../../@services/hikingFinances.service';
import { IHikingData } from '../../@types/hiking.types';
import { IHikingReceipt } from '../../@types/hikingFinances.types';

export interface IEditReceiptParticipationModalProps {
  receipt: IHikingReceipt;
  hikingData: IHikingData;
  onChange: (updated: IHikingReceipt) => void;
}
//s@apps/Hiking/finance/HikingFinancesModals/EditReceiptModal.tsx
const EditReceiptParticipationModal: React.FC<IEditReceiptParticipationModalProps> = ({
  receipt,
  hikingData,
  onChange,
}) => {
  const [editData, setEditData] = React.useState<IHikingReceipt>(receipt);
  const [isSaving, setIsSaving] = React.useState(false);
  const [err, setErr] = React.useState<Error>();

  const handleSubmit = async () => {
    try {
      setErr(undefined);
      setIsSaving(true);

      const res = await updateHikingFinancesReceiptParticipation(editData, hikingData.id);
      res && onChange(editData);
    } catch (er) {
      setErr(er as Error);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div
      onClick={(e) => {
        e.stopPropagation();
        e.preventDefault();
      }}
    >
      <PohList
        data={hikingData.hikers.map((hiker) => {
          return {
            key: hiker.idUser,
            disabled: isSaving,
            action: true,
            onClick: () => {
              setEditData((cur) => {
                const curChecked = !!cur.participation?.find((p) => p.id === hiker.idUser);
                let participation: IHikingReceipt['participation'] = cur.participation ?? [];

                if (!curChecked) {
                  participation.push({
                    id: hiker.idUser,
                    fullName: [hiker.name, hiker.surname].join(' '),
                    date: new Date(),
                  });
                } else {
                  participation = participation.filter((p) => p.id !== hiker.idUser);
                }

                if (
                  participation.length === 0 ||
                  participation.length === hikingData.hikers.length
                ) {
                  participation = null;
                }

                return {
                  ...cur,
                  participation,
                };
              });
            },
            content: (
              <span className="m-0">
                <div className="form-check d-flex align-items-center">
                  <input
                    type="checkbox"
                    disabled={isSaving}
                    checked={!!editData.participation?.find((p) => p.id === hiker.idUser)}
                    className="me-2 form-check-input"
                    id={`hiker_participation_${hiker.idUser}`}
                  />
                  <label
                    className="form-check-label"
                    htmlFor={`hiker_participation_${hiker.idUser}`}
                  >
                    {[hiker.name, hiker.surname].join(' ')}
                  </label>
                </div>
              </span>
            ),
          };
        })}
      />
      <footer className="text-end">
        {err && <PohAlert>{err.message}</PohAlert>}
        <PohButton
          variant={ButtonVariant.Primary}
          className="mt-3 ms-auto"
          disabled={isSaving}
          onClick={handleSubmit}
        >
          Обновить
        </PohButton>
      </footer>
    </div>
  );
};

export default EditReceiptParticipationModal;
